SET LOCAL lock_timeout = '2s';
CREATE OR REPLACE FUNCTION private.sig_scope_ok(_uid uuid, _groups text[])
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$
SELECT CASE WHEN _uid IS NULL THEN false WHEN private.is_super_admin(_uid) OR private.is_admin(_uid) THEN true
ELSE EXISTS(SELECT 1 FROM private.role_source_rows(private.base_config()) source JOIN app_roles role ON role.id=source.role_id WHERE source.user_id=_uid AND source.source_kind='slot' AND EXISTS(SELECT 1 FROM unnest(source.permissions) p WHERE p LIKE 'signal.%') AND (role.signal_scope_all OR EXISTS(SELECT 1 FROM unnest(coalesce(_groups,'{}')) g WHERE g=ANY(role.signal_scope) OR (g LIKE 'Khác:%' AND 'Khác'=ANY(role.signal_scope))))) OR (
(NOT EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id=_uid) AND NOT EXISTS (SELECT 1 FROM public.org_assignments a JOIN public.base_title_role_links l ON l.title_id=a.title_id AND a.slot_id IS NULL WHERE a.user_id=_uid AND a.status='active' AND a.starts_at<=now() AND (a.ends_at IS NULL OR a.ends_at>now())))
OR EXISTS(SELECT 1 FROM public.user_roles ur JOIN public.app_roles r ON r.id=ur.role_id WHERE ur.user_id=_uid AND r.signal_scope_all)
OR EXISTS(SELECT 1 FROM public.user_roles ur JOIN public.app_roles r ON r.id=ur.role_id,unnest(coalesce(_groups,'{}')) g WHERE ur.user_id=_uid AND (g=ANY(r.signal_scope) OR (g LIKE 'Khác:%' AND 'Khác'=ANY(r.signal_scope))))
OR EXISTS(SELECT 1 FROM public.org_assignments a JOIN public.base_title_role_links l ON l.title_id=a.title_id AND a.slot_id IS NULL JOIN public.app_roles r ON r.id=l.role_id WHERE a.user_id=_uid AND a.status='active' AND a.starts_at<=now() AND (a.ends_at IS NULL OR a.ends_at>now()) AND l.permission_signature=md5(coalesce(r.permissions,'{}')::text) AND r.signal_scope_all)
OR EXISTS(SELECT 1 FROM public.org_assignments a JOIN public.base_title_role_links l ON l.title_id=a.title_id AND a.slot_id IS NULL JOIN public.app_roles r ON r.id=l.role_id,unnest(coalesce(_groups,'{}')) g WHERE a.user_id=_uid AND a.status='active' AND a.starts_at<=now() AND (a.ends_at IS NULL OR a.ends_at>now()) AND l.permission_signature=md5(coalesce(r.permissions,'{}')::text) AND (g=ANY(r.signal_scope) OR (g LIKE 'Khác:%' AND 'Khác'=ANY(r.signal_scope))))) END;
$function$;
CREATE OR REPLACE FUNCTION public.signal_list_counts(_filter jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ WITH visible AS MATERIALIZED (SELECT * FROM opportunity_signals),base AS MATERIALIZED(SELECT * FROM (SELECT s.* FROM visible s CROSS JOIN (SELECT _filter-'quick'-'status' AS value) f WHERE coalesce((f.value->>'cancelled')::boolean,false)=(s.cancelled_at IS NOT NULL) AND (coalesce(f.value->>'q','')='' OR strpos(lower(s.customer_name),lower(btrim(f.value->>'q')))>0 OR strpos(s.phone,btrim(f.value->>'q'))>0) AND (coalesce(f.value->>'from','')='' OR CASE WHEN f.value->>'basis'='closed' THEN (s.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date ELSE s.detected_on END>=(f.value->>'from')::date) AND (coalesce(f.value->>'to','')='' OR CASE WHEN f.value->>'basis'='closed' THEN (s.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date ELSE s.detected_on END<=(f.value->>'to')::date) AND (coalesce(f.value->>'source','')='' OR s.source=f.value->>'source') AND (coalesce(f.value->>'product','')='' OR f.value->>'product'=ANY(s.products)) AND (coalesce(f.value->>'needGroup','')='' OR f.value->>'needGroup'=ANY(CASE WHEN cardinality(s.need_groups)>0 THEN s.need_groups ELSE array_remove(ARRAY[s.need_group],NULL) END)) AND (coalesce(f.value->>'saleId','')='' OR s.assigned_to::text=f.value->>'saleId') AND (coalesce(f.value->>'creatorId','')='' OR s.created_by::text=f.value->>'creatorId') AND (NOT coalesce((f.value->>'unassigned')::boolean,false) OR s.assigned_to IS NULL) AND (coalesce(f.value->>'lostReason','')='' OR CASE WHEN s.lost_reason LIKE 'Khác%' THEN 'Khác' ELSE s.lost_reason END=f.value->>'lostReason') AND (coalesce(f.value->>'potential','')='' OR coalesce(s.potential,'unrated')=f.value->>'potential') AND (coalesce(f.value->>'labelId','')='' OR EXISTS(SELECT 1 FROM signal_label_links l WHERE l.signal_id=s.id AND l.label_id::text=f.value->>'labelId')) AND (coalesce(f.value->>'stage','')='' OR CASE WHEN s.status IS NULL OR s.status IN ('waiting','contacting') THEN 'intake' WHEN s.status IN ('consulting','quoted') THEN 'advice' WHEN s.status='lost' THEN 'ended' ELSE 'closing' END=f.value->>'stage') AND (coalesce(f.value->>'status',f.value->>'quick','all') IN ('','all') OR CASE WHEN coalesce(f.value->>'status',f.value->>'quick')='unassigned' THEN s.assigned_to IS NULL AND s.status IS NULL ELSE s.status=coalesce(f.value->>'status',f.value->>'quick') END) AND (coalesce(f.value->>'nextFrom','')='' OR s.next_contact_on>=(f.value->>'nextFrom')::date) AND (coalesce(f.value->>'nextTo','')='' OR s.next_contact_on<=(f.value->>'nextTo')::date) AND (coalesce(f.value->>'work','all')='all' OR (f.value->>'work'='high' AND s.potential='high') OR (f.value->>'work'='won' AND s.status='won') OR (f.value->>'work'='overdue' AND s.status IN ('waiting','contacting','consulting','quoted','deposit') AND s.next_contact_on<(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date) OR (f.value->>'work'='action' AND s.status IN ('waiting','contacting','consulting','quoted','deposit') AND (s.next_contact_on<=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date OR (s.potential='high' AND s.next_contact_on IS NULL)))))),needs AS MATERIALIZED(SELECT * FROM (SELECT s.* FROM visible s CROSS JOIN (SELECT _filter-'needGroup' AS value) f WHERE coalesce((f.value->>'cancelled')::boolean,false)=(s.cancelled_at IS NOT NULL) AND (coalesce(f.value->>'q','')='' OR strpos(lower(s.customer_name),lower(btrim(f.value->>'q')))>0 OR strpos(s.phone,btrim(f.value->>'q'))>0) AND (coalesce(f.value->>'from','')='' OR CASE WHEN f.value->>'basis'='closed' THEN (s.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date ELSE s.detected_on END>=(f.value->>'from')::date) AND (coalesce(f.value->>'to','')='' OR CASE WHEN f.value->>'basis'='closed' THEN (s.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date ELSE s.detected_on END<=(f.value->>'to')::date) AND (coalesce(f.value->>'source','')='' OR s.source=f.value->>'source') AND (coalesce(f.value->>'product','')='' OR f.value->>'product'=ANY(s.products)) AND (coalesce(f.value->>'needGroup','')='' OR f.value->>'needGroup'=ANY(CASE WHEN cardinality(s.need_groups)>0 THEN s.need_groups ELSE array_remove(ARRAY[s.need_group],NULL) END)) AND (coalesce(f.value->>'saleId','')='' OR s.assigned_to::text=f.value->>'saleId') AND (coalesce(f.value->>'creatorId','')='' OR s.created_by::text=f.value->>'creatorId') AND (NOT coalesce((f.value->>'unassigned')::boolean,false) OR s.assigned_to IS NULL) AND (coalesce(f.value->>'lostReason','')='' OR CASE WHEN s.lost_reason LIKE 'Khác%' THEN 'Khác' ELSE s.lost_reason END=f.value->>'lostReason') AND (coalesce(f.value->>'potential','')='' OR coalesce(s.potential,'unrated')=f.value->>'potential') AND (coalesce(f.value->>'labelId','')='' OR EXISTS(SELECT 1 FROM signal_label_links l WHERE l.signal_id=s.id AND l.label_id::text=f.value->>'labelId')) AND (coalesce(f.value->>'stage','')='' OR CASE WHEN s.status IS NULL OR s.status IN ('waiting','contacting') THEN 'intake' WHEN s.status IN ('consulting','quoted') THEN 'advice' WHEN s.status='lost' THEN 'ended' ELSE 'closing' END=f.value->>'stage') AND (coalesce(f.value->>'status',f.value->>'quick','all') IN ('','all') OR CASE WHEN coalesce(f.value->>'status',f.value->>'quick')='unassigned' THEN s.assigned_to IS NULL AND s.status IS NULL ELSE s.status=coalesce(f.value->>'status',f.value->>'quick') END) AND (coalesce(f.value->>'nextFrom','')='' OR s.next_contact_on>=(f.value->>'nextFrom')::date) AND (coalesce(f.value->>'nextTo','')='' OR s.next_contact_on<=(f.value->>'nextTo')::date) AND (coalesce(f.value->>'work','all')='all' OR (f.value->>'work'='high' AND s.potential='high') OR (f.value->>'work'='won' AND s.status='won') OR (f.value->>'work'='overdue' AND s.status IN ('waiting','contacting','consulting','quoted','deposit') AND s.next_contact_on<(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date) OR (f.value->>'work'='action' AND s.status IN ('waiting','contacting','consulting','quoted','deposit') AND (s.next_contact_on<=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date OR (s.potential='high' AND s.next_contact_on IS NULL)))))),st AS(SELECT coalesce(status,'unassigned') key,count(*) n FROM base GROUP BY status),ng AS(SELECT g key,count(DISTINCT s.id) n FROM needs s CROSS JOIN LATERAL unnest(CASE WHEN cardinality(s.need_groups)>0 THEN s.need_groups ELSE array_remove(ARRAY[s.need_group],NULL) END) g GROUP BY g),mine AS(SELECT * FROM visible WHERE assigned_to=auth.uid() AND cancelled_at IS NULL) SELECT jsonb_build_object('total',(SELECT count(*) FROM (SELECT s.* FROM visible s CROSS JOIN (SELECT _filter AS value) f WHERE coalesce((f.value->>'cancelled')::boolean,false)=(s.cancelled_at IS NOT NULL) AND (coalesce(f.value->>'q','')='' OR strpos(lower(s.customer_name),lower(btrim(f.value->>'q')))>0 OR strpos(s.phone,btrim(f.value->>'q'))>0) AND (coalesce(f.value->>'from','')='' OR CASE WHEN f.value->>'basis'='closed' THEN (s.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date ELSE s.detected_on END>=(f.value->>'from')::date) AND (coalesce(f.value->>'to','')='' OR CASE WHEN f.value->>'basis'='closed' THEN (s.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date ELSE s.detected_on END<=(f.value->>'to')::date) AND (coalesce(f.value->>'source','')='' OR s.source=f.value->>'source') AND (coalesce(f.value->>'product','')='' OR f.value->>'product'=ANY(s.products)) AND (coalesce(f.value->>'needGroup','')='' OR f.value->>'needGroup'=ANY(CASE WHEN cardinality(s.need_groups)>0 THEN s.need_groups ELSE array_remove(ARRAY[s.need_group],NULL) END)) AND (coalesce(f.value->>'saleId','')='' OR s.assigned_to::text=f.value->>'saleId') AND (coalesce(f.value->>'creatorId','')='' OR s.created_by::text=f.value->>'creatorId') AND (NOT coalesce((f.value->>'unassigned')::boolean,false) OR s.assigned_to IS NULL) AND (coalesce(f.value->>'lostReason','')='' OR CASE WHEN s.lost_reason LIKE 'Khác%' THEN 'Khác' ELSE s.lost_reason END=f.value->>'lostReason') AND (coalesce(f.value->>'potential','')='' OR coalesce(s.potential,'unrated')=f.value->>'potential') AND (coalesce(f.value->>'labelId','')='' OR EXISTS(SELECT 1 FROM signal_label_links l WHERE l.signal_id=s.id AND l.label_id::text=f.value->>'labelId')) AND (coalesce(f.value->>'stage','')='' OR CASE WHEN s.status IS NULL OR s.status IN ('waiting','contacting') THEN 'intake' WHEN s.status IN ('consulting','quoted') THEN 'advice' WHEN s.status='lost' THEN 'ended' ELSE 'closing' END=f.value->>'stage') AND (coalesce(f.value->>'status',f.value->>'quick','all') IN ('','all') OR CASE WHEN coalesce(f.value->>'status',f.value->>'quick')='unassigned' THEN s.assigned_to IS NULL AND s.status IS NULL ELSE s.status=coalesce(f.value->>'status',f.value->>'quick') END) AND (coalesce(f.value->>'nextFrom','')='' OR s.next_contact_on>=(f.value->>'nextFrom')::date) AND (coalesce(f.value->>'nextTo','')='' OR s.next_contact_on<=(f.value->>'nextTo')::date) AND (coalesce(f.value->>'work','all')='all' OR (f.value->>'work'='high' AND s.potential='high') OR (f.value->>'work'='won' AND s.status='won') OR (f.value->>'work'='overdue' AND s.status IN ('waiting','contacting','consulting','quoted','deposit') AND s.next_contact_on<(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date) OR (f.value->>'work'='action' AND s.status IN ('waiting','contacting','consulting','quoted','deposit') AND (s.next_contact_on<=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date OR (s.potential='high' AND s.next_contact_on IS NULL)))))),'status',coalesce((SELECT jsonb_object_agg(key,n) FROM st),'{}')||jsonb_build_object('all',(SELECT count(*) FROM base)),'needs',coalesce((SELECT jsonb_object_agg(key,n) FROM ng),'{}')||jsonb_build_object('all',(SELECT count(*) FROM needs)),'sales',coalesce((SELECT jsonb_agg(DISTINCT assigned_to) FILTER(WHERE assigned_to IS NOT NULL) FROM visible),'[]'),'creators',coalesce((SELECT jsonb_agg(DISTINCT created_by) FROM visible),'[]'),'mine',jsonb_build_object('waiting',(SELECT count(*) FROM mine WHERE status='waiting'),'active',(SELECT count(*) FROM mine WHERE status IN ('contacting','consulting','quoted','deposit')),'quoted',(SELECT count(*) FROM mine WHERE status='quoted'),'won',(SELECT count(*) FROM mine WHERE status='won' AND date_trunc('month',closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')=date_trunc('month',now() AT TIME ZONE 'Asia/Ho_Chi_Minh')))) $$;
CREATE OR REPLACE FUNCTION public.signal_list_page(_filter jsonb DEFAULT '{}',_sort text DEFAULT 'work',_offset integer DEFAULT 0,_limit integer DEFAULT 40) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ WITH filtered AS MATERIALIZED (SELECT * FROM signal_base_filtered(_filter)), assigns AS(SELECT e.signal_id,max(e.created_at) FILTER(WHERE e.detail ? 'to' AND e.detail->'to'='null'::jsonb) unassigned_at,max(e.created_at) FILTER(WHERE e.detail->>'to'=s.assigned_to::text) assigned_at FROM opportunity_signal_events e JOIN filtered s ON s.id=e.signal_id WHERE e.kind='assign' GROUP BY e.signal_id),notes AS(SELECT n.signal_id,max(n.created_at) FILTER(WHERE status_to='waiting' AND status_from IS DISTINCT FROM status_to) waiting_at,max(n.created_at) activity_at FROM opportunity_signal_notes n JOIN filtered f ON f.id=n.signal_id GROUP BY n.signal_id), ranked AS ( SELECT s.*,CASE WHEN s.cancelled_at IS NOT NULL OR s.status IN ('won','lost') THEN 3 WHEN s.assigned_to IS NULL AND s.status IS NULL THEN 0 WHEN s.status='waiting' THEN 1 ELSE 2 END list_priority,CASE WHEN s.cancelled_at IS NOT NULL OR s.status IN ('won','lost') THEN NULL::timestamptz WHEN s.assigned_to IS NULL AND s.status IS NULL THEN coalesce(a.unassigned_at,s.created_at) WHEN s.status='waiting' THEN coalesce(greatest(a.assigned_at,n.waiting_at,s.assigned_at),s.created_at) ELSE NULL::timestamptz END list_wait_since,greatest(s.updated_at,n.activity_at) list_activity_at,CASE WHEN s.cancelled_at IS NOT NULL OR s.status IN ('won','lost') THEN 3 WHEN s.assigned_to IS NULL AND s.status IS NULL THEN 0 WHEN s.status='waiting' THEN 1 ELSE 2 END list_work_priority,NULL::date list_progression_due_on FROM filtered s LEFT JOIN assigns a ON a.signal_id=s.id LEFT JOIN notes n ON n.signal_id=s.id), page AS MATERIALIZED (SELECT s.* FROM ranked s ORDER BY CASE WHEN _sort IN ('work','priority') THEN s.list_work_priority END,CASE WHEN _sort IN ('work','priority') THEN s.list_wait_since END ASC NULLS LAST,CASE WHEN _sort='oldest' THEN s.created_at END ASC,CASE WHEN _sort='newest' THEN s.created_at END DESC,CASE WHEN _sort='soonest' THEN s.next_contact_on END ASC NULLS LAST,CASE WHEN _sort='potential' THEN CASE s.potential WHEN 'high' THEN 0 WHEN 'medium' THEN 1 WHEN 'low' THEN 2 ELSE 3 END END,CASE WHEN _sort='value' THEN s.revenue END DESC NULLS LAST,s.list_activity_at DESC,s.id LIMIT greatest(1,least(_limit,50)) OFFSET greatest(_offset,0)), numbered AS (SELECT s.*,row_number() OVER(ORDER BY CASE WHEN _sort IN ('work','priority') THEN s.list_work_priority END,CASE WHEN _sort IN ('work','priority') THEN s.list_wait_since END ASC NULLS LAST,CASE WHEN _sort='oldest' THEN s.created_at END ASC,CASE WHEN _sort='newest' THEN s.created_at END DESC,CASE WHEN _sort='soonest' THEN s.next_contact_on END ASC NULLS LAST,CASE WHEN _sort='potential' THEN CASE s.potential WHEN 'high' THEN 0 WHEN 'medium' THEN 1 WHEN 'low' THEN 2 ELSE 3 END END,CASE WHEN _sort='value' THEN s.revenue END DESC NULLS LAST,s.list_activity_at DESC,s.id) ord FROM page s), enriched AS (SELECT p.ord,(to_jsonb(p)-'ord'-'address'-'marketing_note'-'potential_updated_by'-'potential_updated_at'-'cancel_reason')||jsonb_build_object('label_ids',coalesce((SELECT jsonb_agg(l.label_id ORDER BY l.label_id) FROM signal_label_links l WHERE l.signal_id=p.id),'[]'),'note_count',(SELECT count(*) FROM opportunity_signal_notes n WHERE n.signal_id=p.id AND signal_note_is_progression(n.note,n.event_type,n.is_progression)),'last_note',(SELECT jsonb_build_object('signal_id',n.signal_id,'created_at',n.created_at,'note',n.note,'event_type',n.event_type) FROM opportunity_signal_notes n WHERE n.signal_id=p.id AND signal_note_is_progression(n.note,n.event_type,n.is_progression) ORDER BY n.created_at DESC,n.id DESC LIMIT 1)) row FROM numbered p) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(row ORDER BY ord) FROM enriched),'[]')) $$;